def isAnagram(string1, string2): 

    # Make sure both strings have the same length 
    if len(string1)!= len(string2): 
        return False

    # Create a dictionary of characters and their counts 
    count_dict = {} 

    for i in range(len(string1)): 
        if string1[i] in count_dict: 
            count_dict[string1[i]] += 1
        else: 
            count_dict[string1[i]] = 1

    for i in range(len(string2)): 
        if string2[i] in count_dict: 
            count_dict[string2[i]] -= 1
        else: 
            return False

    # If all counts are 0, then the strings are anagrams 
    for key in count_dict: 
        if count_dict[key]!= 0: 
            return False

    return True

